export type CartItem = {
  partId: string;
  title: string;
  slug: string;
  oemNumber: string;
  compatibleCars: string[];
  image: string | null;
  quantity: number;
};

export const CART_STORAGE_KEY = "chinalending-cart:v1";

export function createWhatsAppOrderMessage(items: CartItem[]): string {
  const lines: string[] = [
    "Hello.",
    "",
    "I am interested in the following parts:",
    "",
  ];

  items.forEach((item, index) => {
    lines.push(`${index + 1}. ${item.title} × ${item.quantity}`);
    lines.push(`OEM: ${item.oemNumber}`);

    if (item.compatibleCars.length) {
      lines.push(`Compatible with: ${item.compatibleCars.join(", ")}`);
    }

    lines.push("");
  });

  lines.push("Please confirm price and availability.");

  return lines.join("\n");
}
